Non-perturbative QCD effects generate an effective potential for the
axion whose minimum dynamically cancels the effective CP-violating
parameter $\bar\theta$, thereby solving the strong CP problem. The axion mass is
inversely proportional to the PQ symmetry-breaking scale~\cite{Gorghetto:2018ocs},
%
\begin{equation}
    m_a \simeq 5.7 \; \mu{\rm eV}
    \left( \frac{10^{12} \; {\rm GeV}}{f_a} \right).
    \label{eq:axionmass}
\end{equation}

where the couplings to photons and fermions depend on the ultraviolet
realization of the PQ symmetry. The axion--photon coupling is
conventionally parameterized as
%
\begin{equation}
    g_{a\gamma\gamma} = \frac{\alpha_{\rm em}}{2\pi f_a}
    \left( \frac{E}{N} - 1.92 \right),
    \label{eq:gagg}
\end{equation}
%
where $E$ and $N$ denote the electromagnetic and color anomaly
coefficients, respectively. The ratio $E/N$ therefore distinguishes
different invisible axion models.

\textbf{Model } & \textbf{E/N}\\ \hline
\makebox[11em][c]{DFSZ I - Type I, II or Zee} & 8/3 \\ \hline
\makebox[8em][c]{DFSZ I - Type III} & 11/3 \\ \hline
\makebox[8em]{DFSZ II - Type I, II or Zee} & 2/3 \\ \hline
\makebox[8em]{DFSZ II - Type III} & 5/3 \\ \hline
\end{tabular}
%\end{subtable}
\caption{Values of $E/N$ for the DFSZ scenarios.}

Throughout this work we consider three simple realizations,
%
\begin{itemize}
\item  {\rm KSVZ~I:}
$D_{L,R}\sim(3,1,-1/3)$, 
\item {\rm KSVZ~II:}
$U_{L,R}\sim(3,1,2/3)$, 
\item {\rm KSVZ~III:}
$Q_{L,R}\sim(3,2,1/6)$,
\end{itemize}
%
whose anomaly coefficients are summarized in Table~II. For simplicity, we assume Type I seesaw for these models. Notice that if we study Type III seesaw, the new triplets will change the coupling to photons as we discussed in the previous section.

Once the singlet scalar develops a vacuum expectation value, the fermionic
octet acquires a Majorana mass,
%
$
M_\rho=
\lambda_\rho v_S \sqrt2,
$
%
while light neutrino masses are generated through the one-loop diagram in Fig.~\ref{fig:CS},
%
\begin{equation}
(M_\nu)_{ij}
=
\frac{\lambda v^2}{16\pi^2}
\sum_k
Y^\nu_{ik}
Y^\nu_{jk}
I(M_{\rho_k},M_\Phi),
\end{equation}
%
where $I(M_{\rho_k},M_\Phi)$ denotes the loop function~\cite{FileviezPerez:2009ud}.

\begin{table}[t]
\centering
\begin{tabular}{|c|c|}
\hline
\textbf{Model } & \textbf{E/N}\\ \hline
Colored Seesaw  I & 0 \\ \hline
Colored Seesaw  II & 16/9 \\ \hline
KSVZ I & 2/3 \\ \hline
KSVZ II & 8/3 \\ \hline
KSVZ III & 5/3 \\ \hline
\end{tabular}
\caption{Values of $E/N$ for the different KSVZ scenarios.}
\label{tableII}

We would like to emphasize that the predictions in the colored seesaw scenarios are quite different, predicting the ratio:
\begin{equation}
g_{a\gamma\gamma}^{I}/g_{a\gamma\gamma}^{II} \sim 14.
\end{equation}
Therefore, the bounds are much stronger in colored seesaw I.
Notice the importance of the JWST and ADMX bounds, which are able to rule out a fraction of the parameter space.

The decay width for the channel with two photons is given by
\begin{equation}
    \Gamma(a \to \gamma\gamma) = \frac{\alpha_{em}^2}{256 \pi^3} (E/N -1.92)^2 \frac{m_a^3}{f_a^2},
\end{equation}
while for the decays into two neutrinos one has
\begin{equation}
    \Gamma(a \to \nu_i \nu_i) = \frac{m_a}{16 \pi}\  \left|\frac{c_{\nu} m_{\nu_i}}{N f_a}\right|^2\sqrt{1-\frac{4 m_{\nu_i}^2}{m_a^2}}.
\end{equation}

The expected differential neutrino flux at Earth, for each neutrino flavor, resulting from the decay of  axion dark matter with mass $m_a$ and lifetime $\tau_a$ is given by~\cite{Arguelles:2022nbl}
\begin{equation}
    \frac{d \Phi_\nu}{dE}= \frac{1}{4 \pi} \frac{1}{m_a \tau_a} \frac{1}{3} \frac{dN}{dE} D(\Omega),
\end{equation}
where  
\begin{equation}
    \frac{dN}{dE}=2 \delta(E-m_a/2).
\end{equation}
The D factor depends on the DM distribution of the galaxy. The D-factor is obtained by integrating the dark matter density distribution, $\rho(x)$, along the line of sight and over the observed solid angle $\Delta \Omega$: 
\begin{equation}
    D = \int d\Omega \int \rho(x)\  dx.
\label{D}
\end{equation}
The value of the D factor for the all sky is $2.65 \times 10^{23}$ GeV $\text{cm}^{-2}$ sr~\cite{Arguelles:2022nbl}.

 In Fig.\ref{fig:energySpectrum} we show the differential neutrino energy spectrum from the axion dark matter decay for colored seesaw I and II scenarios. The predicted spectra are shown for detector energy resolutions of $10\%$ and $15\%$ for a benchmark scenario of axion mass 0.05 eV. Here we take into account the detector's finite energy resolution using a Gaussian function, and the spectrum function $dN/{dE}$ can be written as 
\begin{equation}
    \frac{dN}{dE} =2 \int_0^\infty dE_0 \  \delta (E_0 -m_a/2) \ G(E_\nu,\xi/\omega,E_0),
\end{equation}
with
\begin{equation}
    G(E_\nu,\xi/\omega,E_0) = \frac{1}{\sqrt{2\pi}E_0 (\xi/\omega)} \ e^{-\frac{(E_\nu -E_0)^2}{2 E_0^2(\xi/\omega)^2}},
\end{equation}
where $\xi$ defines the energy resolution of the detector and $\omega= 2\sqrt{2\text{log}2}$ determines the full width at half maximum with the standard deviation and the standard deviation is given by $\sigma_0 = E_0 \xi/\omega$. 
 The comparison between the two scenarios shows that the predicted neutrino spectrum changes significantly for different values of the anomaly coefficients of E and N. 
 Notice that the flux is large and
 these spectral features can provide a distinctive signature for probing axion dark matter at future neutrino observations.

\section{DFSZ N Factor}
%%%%%%%%%%%%%%%%%%%%%%%%%
After SSB, there is a phase in the mass terms that must be rotated away. This can be done by taking:
\[ u_R \rightarrow e^{-i\chi_u \frac{a}{v_a}}u_R , d_R \rightarrow e^{-i\chi_d \frac{a}{v_a}}d_R ,\]
Each rotation will give a term in the form:
\begin{equation}
    \mathcal{L}\supset \frac{\alpha_S}{8\pi} a \frac{N}{v_a} G_{\mu \nu} ^a G^{\mu \nu} _a
\end{equation}
where $N = 2 \chi d(r)T_D(R) \times n $. This coefficient contains an extra factor of 1/2 for chiral fields,  $n$ is the number of fermion families, and $\chi$ represents the PQ charge. 

Using the rotations above we get:
\begin{equation}
    N = 3 \times2[(1/2)(1)\chi_u + (1/2)(1)\chi_d] = 3(\chi_u + \chi _d)
\end{equation}
In the convention where $\chi_S=1$, N=6.

It is worth noting that it will also be a necessary rotation from the electron mass term, however, this will not impact the gluon coupling as $T_D(R)=0$ for leptons.

\section{DFSZ E Factor}
The previous rotations will also produce a photon-coupling term in the form:
\begin{equation}
    \mathcal{L} \supset \frac{g_{a\gamma \gamma}}{4} a(x) F_{\mu \nu} \tilde{F}^{\mu \nu}
\end{equation}
with the coupling cosntant $g_{a\gamma\gamma}$ defined as
\begin{equation}
    g_{a\gamma\gamma} = \frac{\alpha_{EM}}{2\pi f_a} \left(\frac{E}{N}-1.92\right),
\end{equation}
and $E = 2\chi d(C_Q)Tr(Q_\rho ^2) \times n$

The quark rotations will take on the following form:
\begin{equation}
    E = 3\times 3 \times2[(-1/3)^2 \chi_d + (2/3)^2 \chi_u]
    \label{E}
\end{equation}
In this scenario, we must also consider the electron rotation, as its impact will now be nonzero. The electron coupling is dependent on the DFSZ model. In DFSZ-Type I, the electron will couple to $H_d$, while in DFSZ-Type II it will couple to $H_u^*$. This gives the following Lagrangian terms and E contributions:
\begin{itemize}

\item DFSZ-Type I : $\mathcal{L} \supset \bar{e_L} e_R e^{i\chi_d \frac{a}{v_a}} \rightarrow E = 3\chi_d (-1)^2 $

\item DFSZ-Type II : $\mathcal{L} \supset \bar{e_L} e_R e^{-i\chi_u \frac{a}{v_a}} \rightarrow E= -3\chi_u(-1)^2$
\end{itemize}
Combing the $E$ contributions from the quarks with the electron, the result for each type is $E_{DFSZ-I} = 8(\chi_u +\chi_d)$ and  $E_{DFSZ-II} = 2(\chi_u +\chi_d)$.

In other DFSZ models (DFSZ with Type III seesaw) additional fermionic fields may be added. In the case of adding $\rho_R \sim (1, 3, 0)$ the Lagrangian will have the term:
\begin{equation}
    {\cal{L}}_{DFSZ}^{III} \supset Y_\nu \ \bar{\ell}_L H_u \rho_R \ + \ \lambda_\rho \rho_R^T C \rho_R S \ + \ \rm{h.c.} 
\end{equation}
The coupling to $S$ requires the new fermion field to be rotated by:
\begin{equation}
    \rho_R \rightarrow \rho_R e^{-i\chi_s \frac{a}{2v_a}}
\end{equation}
which leaves the coupling term 
\begin{equation}
    \mathcal{L} \supset Y_\nu \bar{\ell_L} \rho_R e^{-i ({\chi_S /2 - \chi_u})\frac{a}{v_a}}
\end{equation}.  
This phase can now be rotated away by taking:
\begin{equation}
    \bar{\ell_L} \rightarrow \bar{\ell_L} e^{i ({\chi_S /2 - \chi_u})\frac{a}{v_a}}
\end{equation}
After rotating the left handed field, one must also consider the coupling term between $\bar{\ell_L}$ and $e_R$, which becomes:
\begin{equation}
    \mathcal{L} \supset Y\bar{\ell_L}e_R e^{-i{(\chi_u - \chi_s / 2 -\chi_d) \frac{a}{v_a}}}
\end{equation}
in the case of DFSZ-Type 1. In DFSZ-Type 2, it is the following:
\begin{equation}
    \mathcal{L} \supset Y\bar{\ell_L}e_R e^{-i{(\chi_u - \chi_s / 2 +\chi_u) \frac{a}{v_a}}}
\end{equation}
Following the same process, these phases can be rotated by transforming $e_R$. The final result, accounting for the rotations on $\rho_R$, $\bar{\ell_L}$, $e_R$, and the quarks gives:
\begin{itemize}
    \item DFSZ I- Type III: $E = 11(\chi_u +\chi_d)$
    \item DFSZ II - Type III: $E = 5(\chi_u + \chi_d)$
\end{itemize}
